"eli":{"n":"以利","r":"大祭司和士師","m":"上升；上去","s":"他審判以色列40年，卻沒有管教他那些敗壞的兒子。他聽到約櫃被奪的消息，就向後跌倒死了，享年98歲。","note":"死時98歲（撒母耳記上4:15,18）；年份是大約的。","e":["在示羅祝福哈拿","被警告有關他兒子的事","約櫃被奪；98歲去世"],"src":{"d":"1200001290","t":"以利"}},
"abdon-2":{"n":"押頓","r":"便雅憫族的長子","m":"源自意思是僕人的詞根","s":"便雅憫族耶利的長子，看來是掃羅王的祖父尼珥的兄弟。","src":{"d":"1200000016","t":"押頓"}},
"ahio-1b":{"n":"亞希約","r":"便雅憫族人","m":"亞希雅的簡稱","s":"便雅憫族人，耶利和妻子瑪迦所生的兒子。","src":{"d":"1200000162","t":"亞希約"}},
"elkanah-4":{"n":"以利加拿","r":"撒母耳的父親","m":"上帝已經產生","s":"住在以法蓮山區拉瑪的利未人，每年都到示羅崇拜。他是哈拿和比妮拿的丈夫，哈拿禱告之後，他們生了撒母耳。","src":{"d":"1200001326","t":"以利加拿"}},
"hannah":{"n":"哈拿","r":"撒母耳的母親","m":"恩寵；恩典","s":"她不能生育，常受譏諷，就向上帝傾心吐意地禱告，許願把兒子獻給耶和華。後來她把撒母耳帶到聖幕，還唱了一首帶有預言的歌。","note":"聖經沒有記載。《效法他們的信心》把她的出生時間定在約公元前13世紀末，年份是約數。","e":["在示羅禱告","生下撒母耳","把撒母耳帶到聖幕；唱歌讚美"],"src":{"d":"1200001861","t":"哈拿"}},
"jephthah":{"n":"耶弗他","r":"士師；守誓願的人","m":"願他打開","s":"他被兄弟趕走，後來被召回去跟亞捫人作戰。他遵守誓願，讓獨生女一生在聖幕服務。他做士師六年。","note":"他說以色列人征服那地已有300年（士師記11:26），由此推算他在約公元前1173年；壽命是假定的。","e":["打敗亞捫人","履行誓願","做士師6年後去世"],"src":{"d":"1200002413","t":"耶弗他"}},
"jeroham-1":{"n":"耶羅罕","r":"撒母耳的祖父","m":"願他蒙憐憫","s":"哥轄族的利未人，以利加拿的父親，先知撒母耳的祖父。","src":{"d":"1200002432","t":"耶羅罕"}},
"peninnah":{"n":"比妮拿","r":"以利加拿的妻子","m":"珊瑚","s":"以利加拿的妻子，有很多兒女，常常譏諷丈夫偏愛卻不能生育的哈拿。","src":{"d":"1200003429","t":"比妮拿"}},
"jephthah-s-daughter":{"n":"耶弗他的女兒","r":"終身在聖幕服務","s":"耶弗他的獨生女。父親打勝仗回來時，她出來迎接，並甘願讓父親履行誓願：她一生在耶和華的殿服務，終身不嫁。以色列的年輕女子每年都去稱頌她。"},
"manoah":{"n":"瑪挪亞","r":"參孫的父親","s":"住在瑣拉的但族人，敬畏上帝。天使告訴他不能生育的妻子，她會生一個離俗人兒子。他獻上祭物，看見天使在火焰中升上去。","src":{"d":"1200002889","t":"瑪挪亞"}},
"shimrath":{"n":"申拉","r":"便雅憫族的族長","m":"源自意思是看守的詞根","s":"示每的九個兒子之一，住在耶路撒冷的族長。","src":{"d":"1200004051","t":"申拉"}},
"manoah-s-wife":{"n":"瑪挪亞的妻子","r":"參孫的母親","s":"不能生育的婦人。耶和華的天使向她顯現，預告她會生一個兒子，這兒子一出生就是離俗人。後來她生了參孫。"},
"ibzan":{"n":"以比讚","r":"以色列的士師","s":"繼耶弗他之後做以色列的士師七年。他有30個兒子和30個女兒，死後葬在伯利恆，這個伯利恆可能在西布倫境內。","src":{"d":"1200002129","t":"以比讚"}},
"ner":{"n":"尼珥","r":"掃羅王的祖父","m":"燈","s":"便雅憫族人，亞別（耶利）的兒子，押尼珥和基士的父親，掃羅的祖父。","src":{"d":"1200003226","t":"尼珥"}},
