"eleasah-1":{"n":"以利亞薩","r":"猶大族的耶拉篾後代","m":"上帝已經做成","s":"希利斯的兒子，西斯邁的父親。他是猶大的後代，經由耶拉篾和埃及人耶哈傳下來。","src":{"d":"1200001286","t":"以利亞薩"}},
"elon-3":{"n":"以倫","r":"以色列的士師","m":"可能指大樹","s":"西布倫族人，做以色列的士師十年，死後葬在亞雅崙。","src":{"d":"1200001333","t":"以倫"}},
"gaal":{"n":"迦阿勒","r":"示劍的叛亂首領","m":"可能指憎惡；被憎惡","s":"以伯的兒子，煽動示劍人背叛亞比米勒。他打了敗仗，和兄弟被西布勒趕走。","rn":{"father":["以伯"]},"src":{"d":"1200001578","t":"迦阿勒"}},
"hachmoni-1":{"n":"哈革摩尼","r":"雅朔班的祖先","m":"可能指有智慧","s":"撒巴第業和雅朔班的祖先。雅朔班是大衛三大勇士的首領；哈革摩尼可能是可拉的後代。","src":{"d":"1200001795","t":"哈革摩尼"}},
"hophni":{"n":"何弗尼","r":"邪惡的祭司，以利的兒子","m":"蝌蚪","s":"大祭司以利的兒子。他和弟弟非尼哈褻瀆聖幕，行為不道德。非利士人奪走約櫃那天，他死了。","src":{"d":"1200002069","t":"何弗尼"}},
"ichabod":{"n":"以迦博","r":"以利的孫子","m":"榮耀在哪裡呢？","s":"非尼哈的兒子，在父親死後出生。他母親臨死時給他取這個名字，表示約櫃被奪、以色列失去了榮耀。","src":{"d":"1200002131","t":"以迦博"}},
"mikloth-1":{"n":"米基羅","r":"便雅憫族人，示米亞的父親","s":"示米亞的父親，是住在基遍的便雅憫族人耶利的後代。","src":{"d":"1200003048","t":"米基羅"}},
