"samuel":{"n":"撒母耳","r":"先知，最後一位士師","m":"上帝的名","s":"從小在聖幕服務。他做先知和士師，膏立了以色列最早的兩位君王掃羅和大衛，一生忠心不渝。","note":"在大衛做王之前去世（撒母耳記上25:1）。","e":["小時候蒙耶和華呼召","膏立掃羅","膏立年輕的大衛","去世；以色列人都哀悼他","勇敢地把耶和華的判決告訴以利"],"src":{"d":"1200003824","t":"撒母耳"}},
"shimeam":{"n":"示米暗","r":"便雅憫族人，掃羅的親族","s":"米基羅的兒子，看來住在耶路撒冷；在歷代志上第8章叫示米亞。","aka":["示米亞"],"src":{"d":"1200004044","t":"示米暗"}},
"phinehas-2":{"n":"非尼哈","r":"邪惡的祭司，以利的兒子","s":"祭司以利的小兒子。他和哥哥何弗尼濫用祭物，褻瀆聖幕。兩兄弟在同一天跟非利士人作戰時死了；他的遺孀生下以迦博後也死了。","src":{"d":"1200003472","t":"非尼哈"}},
"jesse":{"n":"耶西","r":"大衛王的父親","m":"耶和華使人忘記","s":"住在伯利恆的猶大人，擁有羊群，是波阿斯和路得的孫子。他有八個兒子，最小的大衛被撒母耳膏立為王。他是耶穌的祖先。","src":{"d":"1200002449","t":"耶西"}},
"abdon-1":{"n":"押頓","r":"以色列的士師","m":"源自意思是僕人的詞根","s":"以法蓮族的士師，平安地領導以色列八年。他有40個兒子和30個孫子騎著驢，可見他很富有。","src":{"d":"1200000016","t":"押頓"}},
"kish-3":{"n":"基士","r":"掃羅王的父親","s":"住在基比亞的富有的便雅憫族人，尼珥的兒子，押尼珥的兄弟。他曾派掃羅去找走失的母驢。","src":{"d":"1200002631","t":"基士"}},
"samson-s-wife":{"n":"參孫的妻子（亭拿的非利士女子）","r":"參孫的非利士妻子","s":"參孫娶的亭拿非利士女子。她受同族人逼迫，套出了參孫的謎底；後來非利士人把她燒死了。"},
"ahitub-1":{"n":"亞希突","r":"祭司，以利的孫子","m":"我的弟兄是善","s":"非尼哈的兒子，以利的孫子，屬以泰瑪一脈。他可能在他們之後做大祭司，是亞希米勒的父親。","src":{"d":"1200000170","t":"亞希突"}},
"amariah-1":{"n":"亞瑪利雅","r":"祭司，以利亞撒的後代","m":"耶和華已經說了","s":"亞倫家族中以利亞撒一脈的祭司，米拉約的兒子，撒督的祖父；他是否做過大祭司並不確定。","src":{"d":"1200000219","t":"亞瑪利雅"}},
"barzillai-1":{"n":"巴西萊","r":"亞得列的父親","m":"屬於鐵","s":"米何拉人，他的兒子亞得列娶了掃羅的女兒梅拉。","src":{"d":"1200000572","t":"巴西萊"}},
"samson":{"n":"參孫","r":"做士師的離俗人","m":"太陽","s":"一出生就是離俗人，上帝賜給他非凡的力量。他被黛利拉出賣，被非利士人弄瞎眼睛，最後推倒大袞的神廟，跟敵人同歸於盡。","note":"在非利士人的時代做士師20年；年份是假定的。","e":["徒手殺死獅子","用驢腮骨擊殺1000人","被黛利拉出賣；推倒大袞的廟"],"rn":{"spouses":["參孫的妻子（亭拿的非利士女子）"]},"src":{"d":"1200003823","t":"參孫"}},
"saul":{"n":"掃羅","r":"以色列的第一個君王","m":"向上帝求來的","s":"起初高大又謙虛，後來變得自以為是、不服從上帝。他被上帝拒絕後，一直追殺大衛，最後求問通靈的女人，在基利波山上死了。","note":"在位40年（使徒行傳13:21）；登基時的年紀不確定。","e":["被膏立為王","擅自獻祭","因亞瑪力人的事不服從而被拒絕","求問隱多珥的通靈女人；死在基利波山"],"src":{"d":"1200003847","t":"掃羅"}},
"abijah-3":{"n":"亞比雅","r":"腐敗的審判官，撒母耳的兒子","m":"我的父親是耶和華","s":"撒母耳的次子，和哥哥約珥被派到別示巴做審判官。他們收受賄賂，促使以色列人要求立王。","src":{"d":"1200000041","t":"亞比雅"}},
"joel-5":{"n":"約珥","r":"撒母耳的長子，審判官","m":"耶和華是上帝","s":"撒母耳的長子，和弟弟亞比雅一起被派做審判官。他們不誠實，促使以色列人要求立王。他是歌手希曼的父親。","aka":["瓦示尼"],"src":{"d":"1200002481","t":"約珥"}},
"nahash-2":{"n":"拿轄","r":"亞比該的父母","m":"蛇","s":"大衛的姊妹亞比該的父或母，可能也是洗魯雅的；拿轄可能是耶西妻子的前夫，也可能是耶西的另一個名字。","src":{"d":"1200003167","t":"拿轄"}},
